import {fields,labels,parseDelimited,detectMapping,mapRows,validate,raggedRows,sample} from './core.mjs';import {loadCatalog} from './catalog.mjs';import {prepare,render} from './poster.mjs';import {defaultBrand} from './brand.mjs';
const $=id=>document.getElementById(id);let rows=[],catalog,prepared,page=0,version=0,raw=[],workbook=null,objectUrl=null,timer,logo='';
// Text fields map 1:1 onto brand keys; the logo is held separately because it is a data: URL, not typed.
const BRAND_FIELDS=['name','tag','sticky','notes','footnote','watchOn','site','whatsapp','cta'];
const STORE='universe-match-studio:brand';
const config=()=>{const b=defaultBrand();for(const k of BRAND_FIELDS){const el=$('brand-'+k);if(el)b[k]=el.value;}b.logo=logo;b.showCta=$('brand-showCta')?.checked??true;return b;};
const now=new Date();$('date').value=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
function error(msg){$('errors').textContent=msg;$('errors').hidden=!msg;}
function status(msg){$('status').textContent=msg;}
function make(tag,attrs={},txt=''){const el=document.createElement(tag);Object.assign(el,attrs);if(txt)el.textContent=txt;return el;}
function schedule(){version++;$('download').disabled=true;clearTimeout(timer);timer=setTimeout(update,220);}
function editor(){const frag=document.createDocumentFragment();rows.forEach((row,i)=>{const card=make('article',{className:'match'});const head=make('div',{className:'match-head'});head.append(make('b',{},String(i+1).padStart(2,'0')));const league=make('input',{value:row.league,placeholder:'الدوري'});league.setAttribute('aria-label',`الدوري للمباراة ${i+1}`);league.oninput=()=>{row.league=league.value;schedule();};const del=make('button',{type:'button'},'×');del.setAttribute('aria-label',`حذف المباراة ${i+1}`);del.onclick=()=>{rows.splice(i,1);editor();schedule();};head.append(league,del);card.append(head);const grid=make('div',{className:'match-grid'});for(const f of ['home','away','time','channel','commentator']){const label=make('label',{},labels[fields.indexOf(f)]);const input=make('input',{value:row[f],type:'text'});input.maxLength=160;if(f==='time')input.inputMode='numeric';input.oninput=()=>{row[f]=input.value;schedule();};label.append(input);grid.append(label);}card.append(grid);const bottom=make('div',{className:'match-bottom'}),label=make('label',{className:'check'}),check=make('input',{type:'checkbox',checked:row.featured});check.onchange=()=>{row.featured=check.checked;schedule();};label.append(check,document.createTextNode('★ مباراة مميزة'));const moves=make('div');for(const [dir,txt] of [[-1,'↑'],[1,'↓']]){const b=make('button',{className:'subtle',disabled:i+dir<0||i+dir>=rows.length},txt);b.setAttribute('aria-label',dir<0?'نقل لأعلى':'نقل لأسفل');b.onclick=()=>{[rows[i],rows[i+dir]]=[rows[i+dir],rows[i]];editor();schedule();};moves.append(b);}bottom.append(label,moves);card.append(bottom);frag.append(card);});$('matches').replaceChildren(frag);$('count').textContent=`${rows.length} مباراة`;}
function draw(){if(!prepared)return;page=Math.max(0,Math.min(page,prepared.pages.length-1));render($('poster'),prepared.pages[page],$('date').value,catalog,prepared.images,page,prepared.pages.length,config());$('pages').textContent=`${page+1} / ${prepared.pages.length}`;$('prev').disabled=page===0;$('next').disabled=page===prepared.pages.length-1;}
async function update(){const ticket=++version;const problems=validate(rows);if(!$('date').value)problems.push('اختر تاريخ المباريات');error(problems.slice(0,12).join('\n'));$('download').disabled=true;if(problems.length){status('المعاينة السابقة لا تتضمن التعديلات غير المكتملة. صحّح البيانات للتنزيل.');return;}$('loading').hidden=false;try{const next=await prepare(rows,catalog,config());if(ticket!==version)return;prepared=next;draw();$('warnings').hidden=!next.unknown.length;$('warnings').textContent='شعارات غير متاحة: '+next.unknown.join('، ')+' — ستظهر علامة محايدة.';$('download').disabled=false;status(`جاهز للتنزيل · ${rows.length} مباراة · ${next.pages.length} بوستر`);}catch(e){if(ticket===version){error(e.message);status('تعذر تحديث المعاينة');}}finally{if(ticket===version)$('loading').hidden=true;}}
// autoDetect only on a fresh import: rebuilding after a manual toggle must respect the user's choice.
function mapUI(autoDetect){const mapping=detectMapping(raw[0]||[]);if(autoDetect)$('has-header').checked=mapping.filter(x=>x>=0).length>=3;const host=$('mapping-fields');host.replaceChildren();fields.forEach((f,i)=>{const l=make('label',{},labels[i]),s=make('select',{id:'map-'+f});s.append(make('option',{value:'-1'},'غير موجود'));const n=Math.max(...raw.slice(0,10).map(r=>r.length));for(let j=0;j<n;j++)s.append(make('option',{value:String(j)},`${j+1}: ${String(raw[0]?.[j]??'').slice(0,35)}`));s.value=String(mapping[i]>=0?mapping[i]:$('has-header').checked?-1:i<n?i:-1);l.append(s);host.append(l);});$('mapping').hidden=false;}
function stage(data){if(!data.length)throw Error('الجدول فارغ');if(data.length>301)throw Error('الحد الأقصى 300 مباراة');raw=data;mapUI(true);error('');const ragged=raggedRows(data);status(ragged.length?`تنبيه: الصفوف ${ragged.slice(0,8).join('، ')} عدد أعمدتها مختلف عن الصف الأول — راجع ربط الأعمدة.`:'راجع ربط الأعمدة ثم اضغط «استخدام هذا الجدول».');}
$('import').onclick=()=>{try{$('sheets').hidden=true;stage(parseDelimited($('paste').value));}catch(e){error(e.message);}};
$('apply').onclick=()=>{try{const mapping=fields.map(f=>Number($('map-'+f).value));const chosen=mapping.filter(x=>x>=0);if(new Set(chosen).size!==chosen.length)throw Error('لا يمكن ربط عمود واحد بحقلين');const next=mapRows(raw.slice($('has-header').checked?1:0),mapping);rows=next;page=0;editor();$('mapping').hidden=true;schedule();}catch(e){error(e.message);}};
$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('حجم الملف أكبر من 10 MB');if(!/\.(xlsx|xls|csv)$/i.test(f.name))throw Error('اختر Excel أو CSV');if(/\.csv$/i.test(f.name)){$('sheets').hidden=true;stage(parseDelimited(await f.text()));}else{if(!window.XLSX)throw Error('تعذر تحميل قارئ Excel. أعد فتح الصفحة.');workbook=XLSX.read(await f.arrayBuffer(),{type:'array',cellFormula:false,sheetRows:302});$('sheet').replaceChildren(...workbook.SheetNames.map(n=>make('option',{value:n},n)));$('sheets').hidden=workbook.SheetNames.length<2;readSheet();}}catch(err){error(err.message);}finally{e.target.value='';}};
function readSheet(){try{const sheet=workbook.Sheets[$('sheet').value];if(sheet['!fullref']){const range=XLSX.utils.decode_range(sheet['!fullref']);if(range.e.r-range.s.r>300)throw Error('الحد الأقصى 300 مباراة');}stage(XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true,blankrows:false}));}catch(e){error(e.message);}}
$('sheet').onchange=readSheet;
// The column dropdowns default differently depending on whether row 1 is a header,
// so toggling the checkbox has to rebuild them rather than only affect the later apply.
$('has-header').onchange=()=>{if(raw.length)mapUI(false);};
$('example').onclick=()=>{$('paste').value=sample;stage(parseDelimited(sample));};
$('add').onclick=()=>{if(rows.length>=300){error('الحد الأقصى 300 مباراة');return;}rows.push({id:Date.now(),league:rows.at(-1)?.league||'',home:'',away:'',time:'',commentator:'',channel:'',featured:false});editor();schedule();$('matches').lastElementChild.scrollIntoView({block:'center',behavior:'smooth'});};
$('date').onchange=schedule;$('prev').onclick=()=>{page--;draw();};$('next').onclick=()=>{page++;draw();};
// Identity settings live in index.html now; this only wires them up, persists them and repaints.
function readStore(){try{return JSON.parse(localStorage.getItem(STORE))||{};}catch{return {};}}
function writeStore(){try{const b=config();localStorage.setItem(STORE,JSON.stringify(b));}catch{/* private mode, or quota: the poster still renders */}}
function applyBrand(b){for(const k of BRAND_FIELDS){const el=$('brand-'+k);if(el&&typeof b[k]==='string')el.value=b[k];}if($('brand-showCta')&&typeof b.showCta==='boolean')$('brand-showCta').checked=b.showCta;logo=typeof b.logo==='string'?b.logo:'';paintLogo();}
function paintLogo(){const slot=$('brand-logo-preview');if(!slot)return;slot.replaceChildren();if(logo)slot.append(make('img',{src:logo,alt:'شعارك'}));$('brand-logo-clear').hidden=!logo;}
// The logo is redrawn from prepare(), so a change has to go through the full update, not just draw().
const brandChanged=()=>{writeStore();schedule();};
for(const k of BRAND_FIELDS){const el=$('brand-'+k);if(el)el.oninput=brandChanged;}
if($('brand-showCta'))$('brand-showCta').onchange=brandChanged;
$('brand-logo').onchange=async e=>{const f=e.target.files[0];e.target.value='';if(!f)return;try{
if(f.size>2*1024*1024)throw Error('حجم الشعار أكبر من 2 MB');
if(!/^image\/(png|jpeg|webp|svg\+xml)$/.test(f.type))throw Error('اختر صورة PNG أو JPG أو WebP أو SVG');
logo=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result));r.onerror=()=>rej(Error('تعذر قراءة الشعار'));r.readAsDataURL(f);});
paintLogo();brandChanged();}catch(err){error(err.message);}};
$('brand-logo-clear').onclick=()=>{logo='';paintLogo();brandChanged();};
$('brand-reset').onclick=()=>{applyBrand(defaultBrand());brandChanged();};
async function png(){return new Promise((resolve,reject)=>$('poster').toBlob(b=>b?resolve(b):reject(Error('تعذر إنشاء الصورة')),'image/png'));}
$('download').onclick=async()=>{try{if($('download').disabled)return;const blob=await png();if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(blob);const a=make('a',{href:objectUrl,download:`Universe-${$('date').value}-${page+1}.png`});document.body.append(a);a.click();a.remove();$('image-link').href=objectUrl;$('image-link').hidden=false;status('تم تجهيز الصورة. لو التنزيل لم يبدأ، افتح الصورة من الرابط أدناه واحفظها.');}catch(e){error(e.message);}};
$('zoom').onclick=async()=>{try{const blob=await png();if($('zoom-image').src.startsWith('blob:'))URL.revokeObjectURL($('zoom-image').src);$('zoom-image').src=URL.createObjectURL(blob);$('zoom-dialog').showModal();}catch(e){error(e.message);}};$('close-zoom').onclick=()=>$('zoom-dialog').close();
async function importText(text){if(typeof text!=='string'||text.length>1000000)throw Error('جدول نصي غير صالح');const matrix=parseDelimited(text);const mapping=detectMapping(matrix[0]||[]);if(mapping.slice(0,4).some(x=>x<0))throw Error('عناوين الأعمدة المطلوبة غير موجودة');const next=mapRows(matrix.slice(1),mapping);const issues=validate(next);if(issues.length)throw Error(issues.join('; '));rows=next;page=0;editor();await update();return {matches:rows.length,pages:prepared.pages.length};}
try{applyBrand({...defaultBrand(),...readStore()});catalog=await loadCatalog();const matrix=parseDelimited(sample);rows=mapRows(matrix.slice(1),detectMapping(matrix[0]));editor();await update();status('مثال توضيحي فقط — استبدله بجدول مبارياتك.');const mc=document.modelContext;if(mc?.registerTool)await mc.registerTool({name:'import_match_table',description:'Replace the visible match table with a validated delimited table and update the poster preview.',inputSchema:{type:'object',properties:{text:{type:'string'}},required:['text'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute:input=>importText(input?.text)});}catch(e){error(e.message);$('loading').hidden=true;}
